-- ---------- Pages ----------
DELETE FROM Pages WHERE Culture = 'fa' AND Slug IN (N'', N'services', N'about', N'contact');   -- their blocks cascade

IF @ArchiveOtherPages = 1
    UPDATE Pages SET Status = 'Archived', UpdatedAt = SYSUTCDATETIME()
    WHERE NOT (Culture = 'fa' AND Slug IN (N'', N'services', N'about', N'contact'));

DECLARE @HomeId uniqueidentifier = NEWID(), @ServicesId uniqueidentifier = NEWID(), @AboutId uniqueidentifier = NEWID(), @ContactId uniqueidentifier = NEWID();

